"""Bounded, self-contained GitHub evidence generated by the VM task."""
import csv
import json
from pathlib import Path

import numpy as np

from .model import save_json, sha

KEYS = ['sink_flux','I_hop_sink','I_form_sink','I_idle_sink','pump_flux','break_flux',
        'sum_pL','sum_pR','inventory','path_probability','B_L_total','B_R_total','M_L_total','E_L_total',
        'pL01','pL12','pL02','I_hop01','I_hop12','I_hop02','I_form01','I_form12','I_form02',
        'I_idle01','I_idle12','I_idle02','formation_current01','formation_current12','formation_current02',
        'n2','dn2_dt']


def stats(t, a):
    lo, hi = int(a.argmin()), int(a.argmax())
    return {'count':len(a),'first':float(a[0]),'last':float(a[-1]),'mean':float(a.mean()),
            'stddev':float(a.std()), 'min':float(a[lo]),'min_time':float(t[lo]),
            'max':float(a[hi]),'max_time':float(t[hi])}


def series(full, cid):
    schema = json.loads((full/'cases'/f'{cid}_schema.json').read_text())
    rows = [json.loads(x) for x in (full/'cases'/f'{cid}.jsonl').read_text().splitlines()]
    t, a = np.array([x['time'] for x in rows]), np.array([x['values'] for x in rows])
    names = schema['observable_names']
    if not len(t) or a.shape != (len(t),len(names)) or not np.isfinite(a).all() or np.any(np.diff(t)<=0):
        raise ValueError('Malformed case series: '+cid)
    return t, a, names


def comparisons(cases, arrays, config):
    out = {'mixtures':[], 'refinements':[], 'contrasts':[], 'predictions':[]}
    if config['mode'] != 'main':
        return out
    for group in config['models']:
        ids = [f'{group}_p{i}' for i in range(4)]
        mid = group+'_mix'
        if mid in arrays and all(cid in arrays for cid in ids):
            t, a, names = arrays[mid]
            phase = np.array([arrays[cid][1] for cid in ids])
            error = float(np.max(np.abs(phase.mean(axis=0)-a)))
            harmonic = float(np.max(np.abs(phase[0]+phase[2]-phase[1]-phase[3])))
            out['mixtures'].append({'model':group,'max_all_observable_error':error,
                                   'harmonic_residual':harmonic,'passed':max(error,harmonic)<=config['acceptance']['mixture_error']})
        fid = group+'_fine'
        if mid in arrays and fid in arrays:
            t,a,names=arrays[mid]
            tf,af,nf=arrays[fid]
            if names != nf or not np.allclose(t,tf,rtol=0,atol=1e-12):
                raise ValueError('Refinement grid mismatch')
            per = np.max(abs(a-af),axis=0)
            out['refinements'].append({'model':group,'max_all_observable_difference':float(per.max()),
                'per_observable':dict(zip(names,per.tolist())),
                'passed':float(per.max())<=config['acceptance']['refinement_observables']})
    for level in ['n0','base','n05']:
        for left,right in [('PS','PP'),('PS','PQ'),('QS','QP'),('QS','QQ')]:
            lid,rid=f'{level}_{left}_mix',f'{level}_{right}_mix'
            if lid not in arrays or rid not in arrays:
                continue
            ts,a,names=arrays[lid]
            tr,b,nb=arrays[rid]
            if names!=nb or not np.array_equal(ts,tr):
                raise ValueError('Comparison grid mismatch')
            for target in [1,5,20,40,100,200]:
                points=np.flatnonzero(np.isclose(ts,target,rtol=0,atol=1e-9))
                if not len(points):continue
                j=int(points[0]); ix=names.index('sink_flux')
                diff=float(a[j,ix]-b[j,ix])
                sensitivity=[]
                for var in [left,right]:
                    row=next((x for x in out['refinements'] if x['model']==level+'_'+var),None)
                    if row:sensitivity.append(row['per_observable']['sink_flux'])
                numerical_bound=10*sum(sensitivity)+1e-10 if len(sensitivity)==2 else None
                out['contrasts'].append({'level':level,'left':left,'right':right,'time':target,
                    'differences':{k:float(a[j,names.index(k)]-b[j,names.index(k)]) for k in KEYS},
                    'F_relative_difference':diff/max(abs(float(b[j,ix])),1e-14),
                    'baseline_dt_sensitivity_bound':numerical_bound,
                    'above_numeric_sensitivity':abs(diff)>numerical_bound if numerical_bound is not None else None,
                    'above_practical_threshold':abs(diff)>config['practical_relative_effect']*max(abs(float(b[j,ix])),1e-14)})
    for variant,bounds in [('QS',[0.1102,0.1111]),('PS',[0.1121,0.1126])]:
        cid='base_'+variant+'_mix'
        if cid not in arrays:continue
        ts,a,names=arrays[cid]; hits=np.flatnonzero(np.isclose(ts,100,atol=1e-9,rtol=0))
        if len(hits):
            f=float(a[int(hits[0]),names.index('sink_flux')])
            out['predictions'].append({'variant':variant,'time':100,'expected_interval':bounds,'actual_F':f,
                                      'within_prediction':bounds[0]<=f<=bounds[1], 'not_a_numerical_acceptance_test':True})
    return out


def prepare_report(root, config, metadata, outcome):
    full,report=root/'full',root/'report'
    report.mkdir(exist_ok=True)
    arrays, metrics, checks, coverage = {},{},[],[]
    for row in outcome['preflight']:
        checks.append({'name':'preflight_'+row['model'],'passed':row['passed'],'actual':row})
    for model,values in outcome['operators'].items():
        checks.append({'name':'operators_'+model,'actual_max':max(values.values()),
                       'limit':config['acceptance']['algebra'],'passed':max(values.values())<=config['acceptance']['algebra']})
    summaries={x['case']['id']:x for x in outcome['cases']}
    for case in config['cases']:
        cid=case['id'];path=full/'cases'/f'{cid}.jsonl'
        if not path.exists():
            metrics[cid]={'status':'not_started','case':case}
            continue
        t,a,names=series(full,cid)
        arrays[cid]=(t,a,names)
        statistics={k:stats(t,a[:,i]) for i,k in enumerate(names)}
        chosen=np.flatnonzero((t<=20+1e-9) | (abs(t/2-np.rint(t/2))<1e-9))
        extrema_indices=[j for k in KEYS for j in [int(a[:,names.index(k)].argmin()),int(a[:,names.index(k)].argmax())]]
        chosen=np.unique(np.r_[chosen,0,len(t)-1,extrema_indices])
        folder=report/'series';folder.mkdir(exist_ok=True)
        with (folder/f'{cid}.csv').open('w',newline='') as f:
            writer=csv.writer(f);writer.writerow(['time',*KEYS])
            for j in chosen:
                writer.writerow([format(float(t[j]),'.17g'),*(format(float(a[j,names.index(k)]),'.17g') for k in KEYS)])
        cov={'case_id':cid,'original_records':len(t),'published_records':len(chosen),
             'original_observables':len(names),'published_series_observables':len(KEYS),
             'all_observable_statistics_cover_records':len(t),'expected_records':round(case['horizon']/config['integration']['observable_interval'])+1}
        coverage.append(cov)
        summary=summaries.get(cid)
        metrics[cid]={'status':'completed' if summary else 'partial','case':case,'summary':summary,
                      'statistics':statistics,'coverage':cov}
        if summary:
            counts=(len(t)==summary['scalar_records'] and
                    np.allclose(t,np.arange(len(t))*config['integration']['observable_interval'],rtol=0,atol=1e-10) and
                    summary['steps']==round(case['horizon']/case['dt']) and
                    summary['scalar_records']==cov['expected_records'] and
                    summary['snapshots']==round(case['horizon']/config['integration']['rho_interval'])+1)
            checks.append({'name':'workload_'+cid,'passed':counts,'actual':{k:summary[k] for k in ['steps','scalar_records','snapshots']},
                           'expected':{'steps':round(case['horizon']/case['dt']),'scalar_records':cov['expected_records'],
                                       'snapshots':round(case['horizon']/config['integration']['rho_interval'])+1}})
    comp=comparisons(metrics,arrays,config)
    checks.extend({'name':'mixture_'+x['model'],**x} for x in comp['mixtures'])
    checks.extend({'name':'refinement_'+x['model'],**x} for x in comp['refinements'])
    checks.append({'name':'all_cases_completed','passed':len(summaries)==len(config['cases']),
                   'actual':len(summaries),'expected':len(config['cases'])})
    checks.append({'name':'snapshot_hashes','passed':outcome.get('retention_passed',False),
                   'actual':outcome.get('verified_snapshots',0)})
    inventory=[]
    for path in sorted(full.rglob('*')):
        if path.is_symlink():raise ValueError('Unexpected symlink')
        if path.is_file():inventory.append({'vm_path':f'results/{metadata["run_id"]}/full/{path.relative_to(full)}',
                                          'bytes':path.stat().st_size,'sha256':sha(path),'format':path.suffix.lstrip('.')})
    manifest={'run_id':metadata['run_id'],'source_commit':metadata['source_commit'],'full_files':inventory,
              'full_file_count':len(inventory),'full_bytes':sum(x['bytes'] for x in inventory),'coverage':coverage,
              'selection':'All 164 observables sampled each 0.2; full rho each 1. GitHub series: 31 declared observables, every 0.2 through 20 then every 2, plus final point AND min/max locations of every one of these 31 observables. Whole-series extrema with times, means and standard deviations for ALL observables use ALL original samples. Ordering/correlations omitted between published rows require full data. No claims between original samples.',
              'input_files':[],'initial_conditions':'Analytic: RRR, node (|100>+exp(i phi)|010>)/sqrt(2), or equal incoherent mixture.',
              'report_partial':outcome.get('failure') is not None}
    save_json(report/'data_manifest.json',manifest)
    result={'run_id':metadata['run_id'],'source_commit':metadata['source_commit'],'mode':config['mode'],
            'cases':metrics,'comparisons':comp,'preflight':outcome['preflight'],
            'operator_checks':outcome['operators'],'failure':outcome.get('failure'),
            'planned_steps':sum(round(c['horizon']/c['dt']) for c in config['cases']),
            'actual_steps':sum(x['steps'] for x in summaries.values()),'planned_cases':len(config['cases']),
            'actual_cases':len(summaries),'environment':metadata,'protocol':config,
            'full_bytes':manifest['full_bytes'],'full_file_count':manifest['full_file_count']}
    return result,checks


def finalize_report(root, result, checks, timing):
    report=root/'report';config=result['protocol']
    result['timing']=timing
    checks=[x for x in checks if x['name']!='runtime_gate']
    checks.append({'name':'runtime_gate',**timing['gate'],'passed':timing['gate']['status']=='PASS'})
    save_json(report/'metrics.json',result)
    save_json(report/'checks.json',checks)
    g=timing['gate']
    lines=['# SQRT — '+result['mode'], '',
        f'Время: прогноз {g["expected_seconds"]:.1f} с; диапазон {g["lower_seconds"]:.1f}–{g["upper_seconds"]:.1f} с; внутренний замер {g["actual_seconds"]:.1f} с; отношение {g["actual_over_expected"]:.3f}; статус {g["status"]}.',
        'Замер заканчивается после основной подготовки отчёта, до его финальной записи; полное время процесса и очередь проверяются по run.json. При REVIEW_REQUIRED научная интерпретация ждёт разбора времени.', '',
        f'Запуск `{result["run_id"]}`. Исходный коммит `{result["source_commit"]}`. Протокол SQRT v001.',
        f'Объём: {result["actual_cases"]}/{result["planned_cases"]} траекторий; {result["actual_steps"]}/{result["planned_steps"]} основных RK4-шагов. Число шагов preflight: {sum(x["rk4_steps"] for x in result["preflight"])}.',
        f'Полные файлы: {result["full_file_count"]}, {result["full_bytes"]} байт. Отчёт не включает матрицы плотности.', '',
        'Вопрос: как растворение sqrt(I−Q) меняет поток и защищённые компоненты по сравнению с Π и I−Q при том же образовании? Это проверка механизма перед E002; повреждения и ремонт здесь не выполняются.',
        'Три узла и три ребра 0/R/L, размерность 216. P=Π=|ψ+><ψ+|; Q=diag(Π). Первая буква задаёт гейт образования; вторая — фактор растворения: P: I−Π, Q: I−Q, S: sqrt(I−Q).',
        'J=1, g=0.5, η=0.25, δ=0.1, κin=κout=0.5, φe=0.05, γr=0.05, γbg=0.01. n0/base/n05 означают φn=0/0.05/0.5. Время в J⁻¹, потоки в обратных единицах модельного времени.',
        'Начало: все рёбра R; узлы (|100>+exp(iφ)|010>)/sqrt(2). p0…p3: φ=0,π/2,π,3π/2; mix: равная некогерентная смесь этих двух узловых конфигураций; fine: та же mix с dt/2.',
        'Главные сравнения: PS−PP и QS−QP по F(T=200); PS−PQ и QS−QQ контролируют отличие от прежнего диагонального растворения. Практический порог 0.1% базового потока; численная различимость в base: 10×сумма чувствительностей к шагу +1e−10. Нулевой или отрицательный эффект сохраняется.',
        'Защита относится только к своему каналу растворения. S и P совпадают по скорости на |01>,|10>, но не по действию на когерентные состояния. Отождествлять различие с одной только защитой ψ+ нельзя.', '']
    if result['failure']:lines += ['**Ошибка:** '+json.dumps(result['failure'],ensure_ascii=False),'']
    lines += ['## Все выполненные случаи и динамика F', '',
              'Стат.: S=пройдено окно стационарности, N=не пройдено. Значения таблиц округлены до 7 значащих; JSON/CSV содержат полную точность.',
              '| Случай | T | Стат. | F финал | min F | max F @ t | среднее ± SD |',
              '|---|---:|---|---:|---:|---:|---:|']
    for cid,r in result['cases'].items():
        s=r.get('summary')
        if not s:
            lines.append(f'| {cid} | — | {r["status"]} | — | — | — | — |');continue
        f=r['statistics']['sink_flux']
        lines.append(f'| {cid} | {s["case"]["horizon"]:g} | {"S" if s["stationarity"]["passed"] else "N"} | {f["last"]:.7g} | {f["min"]:.5g} | {f["max"]:.7g} @ {f["max_time"]:g} | {f["mean"]:.5g} ± {f["stddev"]:.4g} |')
    lines += ['', '## Смеси: каналы и компоненты на конце', '',
              'F — выходной поток; hop/form/idle — вход в узел 2 соответствующих каналов; B/M/E — компоненты при активных связях. B+M+E=sum_pL. B_R — защищённая проекция при ресурсе.',
              '| Модель | hop | form | idle | B_L | M_L | E_L | B_R | pump |',
              '|---|---:|---:|---:|---:|---:|---:|---:|---:|']
    for cid,r in result['cases'].items():
        if not cid.endswith('_mix') or not r.get('summary'):continue
        f=r['summary']['final_observables']
        keys=['I_hop_sink','I_form_sink','I_idle_sink','B_L_total','M_L_total','E_L_total','B_R_total','pump_flux']
        lines.append('| '+cid[:-4]+' | '+' | '.join(format(f[k],'.7g') for k in keys)+' |')
    lines += ['', '## Сравнения и проверки', '', '| φn | сравнение | ΔF при T200 | ΔF/F | численно различимо | >0.1% |',
              '|---|---|---:|---:|---|---|']
    for c in result['comparisons']['contrasts']:
        if c['time']!=200:continue
        lines.append(f'| {c["level"]} | {c["left"]}−{c["right"]} | {c["differences"]["sink_flux"]:.7g} | {c["F_relative_difference"]:.7g} | {c["above_numeric_sensitivity"]} | {c["above_practical_threshold"]} |')
    for c in result['comparisons']['predictions']:
        lines.append(f'Прогноз {c["variant"]} при T100: {c["expected_interval"]}; факт {c["actual_F"]:.12g}; попадание {c["within_prediction"]}. Это прогноз, не критерий корректности.')
    for c in result['comparisons']['refinements']:
        lines.append(f'Шаг/2 {c["model"]}: max Δ всех наблюдаемых={c["max_all_observable_difference"]:.4g}; порог {config["acceptance"]["refinement_observables"]:g}; PASS={c["passed"]}.')
    for c in result['comparisons']['mixtures']:
        lines.append(f'Среднее 4 фаз vs mix {c["model"]}: max Δ={c["max_all_observable_error"]:.4g}; гармонический остаток={c["harmonic_residual"]:.4g}; порог {config["acceptance"]["mixture_error"]:g}.')
    failed=[x['name'] for x in checks if not x['passed']]
    lines += [f'Проверок {len(checks)}, пройдено {len(checks)-len(failed)}. Все провалы: '+(', '.join(failed) if failed else 'нет')+'.',
              'Стационарность: max ||Lρ||/||ρ|| ≤1e−6, размах F/|Fкон| ≤1e−4, ||ρкон−ρнач||/||ρкон|| ≤1e−5 за последние 10. Это конечное окно, не доказательство единственности.',
              'Численные пороги: trace/hermiticity 1e−8; min sampled eigenvalue ≥−1e−7; алгебра 1e−10; preflight RK4/expm 2e−6 и прямой RHS 1e−12. Позитивность проверяется каждые 5, не на каждом шаге.']
    q=[x['summary']['state_quality'] for x in result['cases'].values() if x.get('summary')]
    if q:lines.append(f'Факт по всей серии: max trace {max(x["max_trace_error"] for x in q):.5g}; max hermiticity {max(x["max_hermiticity_error"] for x in q):.5g}; min eigen {min(x["min_sampled_eigenvalue"] for x in q):.5g}.')
    lines += ['', '## Замкнутый пересчёт из этого файла', '',
              'Для каждой базовой смеси ниже четыре числа в порядке F, hop, form, idle и отдельно dn₂/dt. Проверка: dn₂/dt = hop+form+idle−F; ненулевое накопление нельзя потерять.',
              '| Случай | F; hop; form; idle | dn₂/dt |', '|---|---|---:|']
    for cid,r in result['cases'].items():
        if not cid.startswith('base_') or not cid.endswith('_mix') or not r.get('summary'):continue
        f=r['summary']['final_observables']
        lines.append('| '+cid+' | '+'; '.join(format(f[k],'.17g') for k in ['sink_flux','I_hop_sink','I_form_sink','I_idle_sink'])+' | '+format(f['dn2_dt'],'.17g')+' |')
    lines += ['', '## Покрытие и предел вывода', '',
              'metrics.json содержит все конечные 164 наблюдаемые, статистики всех отсчётов, фазовые/шаговые сравнения и интегральные балансы. CSV: 31 величина, шаг 0.2 до T20, далее 2, плюс моменты min/max всех 31 величин. Поэтому их экстремумы пересчитываются из CSV. Матрицы на ВМ каждые 1; все 164 ряда каждые 0.2. Порядок между опубликованными точками и полная ρ сюда не входят.',
              'Различия гейтов, потоков и компонент в заданных режимах проверяемы. Этот пакет не доказывает саморемонт, автопоэзис, BIC, квантовое преимущество или единственный стационар. Уровни n0/n05 — проверка чувствительности; полный dt/2 выполнен только в base.',
              'Калибровка — технический замер, не основной SQRT. Для основного запуска число и горизонт случаев фиксированы; остановки по красивому результату нет.',
              'Источник и условия: config.json выполненного коммита; SHA256 опубликованных файлов — run.json. Полные файлы, размеры, SHA256 и покрытие — data_manifest.json. Проверка содержимого CSV и хешей обязательна отдельно от этого текста.']
    text='\n'.join(lines)+'\n'
    if len(text.encode())>24576:raise RuntimeError('RESULT.md exceeds 24 KiB; no truncation allowed')
    (report/'RESULT.md').write_text(text)
    (report/'README.md').write_text('# SQRT\n\nГлавный самодостаточный результат: [RESULT.md](RESULT.md).\n\nСначала время, затем полнота и численные проверки. Подробности: metrics.json, checks.json, series/, data_manifest.json.\n')
    sizes=[p.stat().st_size for p in report.rglob('*') if p.is_file()]
    if len(sizes)>500 or max(sizes,default=0)>8*1024**2 or sum(sizes)>30*1024**2:
        raise RuntimeError('Report exceeds declared size/count budget')
    return {'bytes':sum(sizes),'files':len(sizes),'result_bytes':len(text.encode())}
